import android.content.Context
import java.util.Calendar

object L{
 fun lang(c:Context)=Store.p(c).getInt("lang",1)
 fun inten(c:Context)=Store.p(c).getInt("int",1)
 private fun pick(s:String,i:Int):String{val p=s.split("|");val v=p.getOrNull(i)?:"";return if(v.isBlank())p[0] else v}
 fun t(c:Context,k:String)=pick(S[k]?:k,lang(c))
 fun f(c:Context,k:String,vararg kv:Pair<String,String>):String{var s=t(c,k);for((a,b) in kv)s=s.replace("{"+a+"}",b);return s}
 private fun fill(c:Context,s:String)=s.replace("{n}",Store.name(c)).replace("{g}",theme(c))
 fun cat(c:Context):String{val cs=Store.goalCats(c);return if(cs.isEmpty())"gen" else cs[Calendar.getInstance().get(Calendar.DAY_OF_YEAR)%cs.size]}
 fun theme(c:Context)=t(c,"th_"+cat(c))
 fun dose(c:Context):String{val cl=Calendar.getInstance();val day=cl.get(Calendar.DAY_OF_YEAR);val s=day*4+cl.get(Calendar.HOUR_OF_DAY)/6
  val a=(A[cat(c)]?:emptyList())+A["gen"]!!;val x=pick(a[(s*7)%a.size],lang(c));val y=pick(B[(s*5+day)%B.size],lang(c));return fill(c,x)+" "+fill(c,y)}
